mapper.select:
SELECT r.id AS id, m.id AS memberId, m.name, m.unique_id, m.profile_image, r.content, r.like_count, r.created_at, r.updated_at FROM reply r JOIN post p ON r.post_id = p.id JOIN member m ON r.member_id = m.id
AND r.post_id = #{postId}
AND r.id > #{cursor}
ORDER BY r.id ASC LIMIT #{limit}
